"""Web console autogenerated certificate (issue #118, ADR-0003).

The console builds its own self-signed certificate when `use_tls` is on and no `ssl_cert` is given.
That path had no test before #118, so the shared identity rule it calls — the X.509 CommonName
ceiling — had never run on this surface.
"""

import os
from types import SimpleNamespace

import pytest
from cryptography import x509
from cryptography.x509.oid import NameOID

from openmux.common.identity import CERT_CN_MAX_LEN
from openmux.server.web_console import WebConsoleAdapter

LONG_ID = "e2e-test_a_console_with_a_long_server_id_still_gets_its_https_listener-hub"


def _console(tls_dir: str, server_id: str) -> WebConsoleAdapter:
    adapter = WebConsoleAdapter("wc", {"web_console": {"host": "127.0.0.1", "port": 0, "enable_ui": False}})
    # The `tls_dir` config key is not honoured here; the directory comes from locations. Assigning it
    # keeps the generated key and certificate inside the test's temp path instead of ~/.openmux.
    adapter.tls_dir = tls_dir
    adapter.main_port_manager = SimpleNamespace(config_manager=SimpleNamespace(config={"server": {"id": server_id}}))
    return adapter


@pytest.mark.asyncio
async def test_autogen_cert_keeps_a_long_server_id_inside_the_common_name_ceiling(tmp_path):
    assert len(LONG_ID) > CERT_CN_MAX_LEN
    adapter = _console(str(tmp_path), LONG_ID)

    cert_path, key_path = await adapter._ensure_autogen_cert()

    cert = x509.load_pem_x509_certificate(open(cert_path, "rb").read())
    names = [str(a.value) for a in cert.subject.get_attributes_for_oid(NameOID.COMMON_NAME)]
    assert os.path.exists(key_path)
    assert len(names) == 1
    cn = names[0]
    assert len(cn) <= CERT_CN_MAX_LEN
    assert cn.startswith(LONG_ID[:20])
    # The rule this replaces cut the id at the ceiling, which handed two nodes sharing a
    # 64-character prefix one label. A plain cut of this id would match here.
    assert cn != LONG_ID[:CERT_CN_MAX_LEN]
    assert ".." in cn
